LOGS = [
    ('web', 'ERROR'), ('web', 'INFO'), ('api', 'ERROR'), ('db', 'ERROR'),
    ('web', 'ERROR'), ('api', 'WARN'), ('db', 'ERROR'), ('web', 'ERROR'),
]
ALERT_THRESHOLD = 3

def error_counts(logs):
    counts = {}
    for service, severity in logs:
        if severity == 'ERROR':
            counts[service] = counts.get(service, 0) + 1
    return counts

def should_alert(count):
    return count >= ALERT_THRESHOLD

counts = error_counts(LOGS)
for service in sorted({s for s, _ in LOGS}):
    n = counts.get(service, 0)
    print(f"{service}: errors={n} alert={'yes' if should_alert(n) else 'no'}")
print(f"total errors: {sum(counts.values())}")
